#!/bin/bash
# RTC — génération des tomes de fondation T1 à T4 : plan (Dialagram, sous contraintes), rédaction, nettoyage, PDF.
# Claude écrit seulement les consignes ci-dessous, puis relit chaque tome avant publication.
O=/home/user/agentsecctest1/bibliotheque/outils
D=/home/user/agentsecctest1/NCE/09_PUBLICATIONS
REGLES="RÈGLES ABSOLUES : (1) ne citer QUE les références de la liste ci-dessous, avec l'auteur et l'année indiqués ; n'en inventer aucune ; aucun DOI, aucun numéro de page, aucune citation entre guillemets attribuée à un chercheur ; (2) ne jamais présenter une intuition comme une preuve ; donner des preuves complètes pour les résultats démontrés dans le livre, et pour les grands théorèmes connus donner l'idée de la preuve en le disant ; (3) chaque affirmation porte un statut : PROUVÉ, CONNU, EXPÉRIMENTAL, CONJECTURE, RÉFUTÉ ou OUVERT ; (4) aucune annonce de découverte ; (5) formules en LaTeX entre \$...\$ ou \$\$...\$\$ ; (6) lecteur cultivé non spécialiste : intuition, définition, énoncé, exemple, exercice ; (7) dernier chapitre : « Transfert vers le programme RTC » (ce que ce tome apporte à l'étude des traductions à ressources : quelles ressources, quelles traductions, quelles questions ouvertes)."

livre() {  # $1 dossier, $2 titre, $3 sujet, $4 références
  mkdir -p $D/$1 && cd $D/$1
  cat > brief_plan.txt <<EOF
Tu es l'auteur, pour le compte d'Oussama Ghorbel, d'un livre de la collection scientifique « Les Traductions du Calcul » (programme de recherche RTC : étudier quelles ressources — taille, temps, mémoire, profondeur, largeur, précision, partage — chaque traduction entre modèles de calcul conserve ou perd). Titre : « $2 ». Sujet : $3

$REGLES

Références autorisées (et seulement elles) : $4

Conçois le plan d'un livre d'environ 220 pages : 4 parties, 16 chapitres (le 16e est le transfert vers RTC), 4 à 6 sections par chapitre, exercices. Réponds UNIQUEMENT avec un JSON valide, sans balises markdown :
{"titre":"$2","sous_titre":"...","these":"...","cadre":{"nom":"Les traductions à ressources et le registre des statuts","description":"(recopie ici intégralement les règles absolues ci-dessus et la liste des références autorisées)"},"bibliographie":[{"auteur":"...","titre":"...","annee":"...","idee":"...","apport":"..."}],"parties":[{"titre":"...","chapitres":[{"numero":1,"titre":"...","objectif":"...","sections":["..."],"exercices":["..."]}]}]}
EOF
  for i in 1 2 3; do
    [ -s plan.json ] && break
    python3 $O/ask.py brief_plan.txt plan_raw.txt
    python3 -c "
import json;t=open('plan_raw.txt').read().strip()
if t.startswith('\`\`\`'): t=t.split('\n',1)[1].rsplit('\`\`\`',1)[0]
p=json.loads(t);assert sum(len(x['chapitres']) for x in p['parties'])>=14
json.dump(p,open('plan.json','w'),ensure_ascii=False,indent=1)" 2>/dev/null || rm -f plan.json
  done
  [ -s plan.json ] || { echo "$1 ERREUR plan"; return; }
  python3 -u $O/redaction.py plan.json chapitres --parallele 4 > redaction.log 2>&1
  python3 -u $O/nettoyage.py chapitres chapitres_v2 > nettoyage.log 2>&1
  python3 $O/mise_en_page.py plan.json chapitres_v2 livre.pdf --corps 11.3 > pdf.log 2>&1
  echo "$1 FIN $(ls chapitres_v2/*.md 2>/dev/null | wc -l) fichiers ; $(tail -1 pdf.log)"
}
REGLES="$REGLES (8) ce tome est un tome de TRADUCTION entre deux modèles : pour chaque traduction, donner le sens, le coût (taille, temps, mémoire, profondeur, largeur, précision, partage), ce qui est conservé et ce qui est perdu, avec son statut."
livre T5 "Du Lambda-calcul aux Machines de Turing" "traductions dans les deux sens entre lambda-calcul et machines de Turing : équivalence de Church-Turing, encodage des machines en lambda-termes, évaluation des lambda-termes par machines (SECD, Krivine, machines à environnement), coût de la bêta-réduction et modèle de coût invariant, perte du partage, explosion de taille, ce qui se conserve (calculabilité) et ce qui se perd (structure, partage, coût fin)." "Church 1936 (An unsolvable problem of elementary number theory) ; Turing 1936 (On computable numbers, with an application to the Entscheidungsproblem) ; Turing 1937 (Computability and lambda-definability) ; Landin 1964 (The mechanical evaluation of expressions) ; Hartmanis et Stearns 1965 (On the computational complexity of algorithms) ; Barendregt 1984 (The Lambda Calculus: Its Syntax and Semantics) ; Lamping 1990 (An algorithm for optimal lambda calculus reduction) ; Krivine 2007 (A call-by-name lambda-calculus machine) ; Arora et Barak 2009 (Computational Complexity: A Modern Approach) ; Accattoli et Dal Lago 2016 ((Leftmost-outermost) beta reduction is invariant, indeed)" &
livre T6 "Des Machines de Turing aux Circuits et à SAT" "traductions machines de Turing vers circuits puis vers SAT : tableau de calcul de Cook-Levin, simulation par circuits de taille O(t log t) (Pippenger-Fischer), uniformité, encodage de Tseitin, coût en variables et clauses, conservation de la structure (largeur, profondeur), sens inverse (circuits vers machines, évaluation), réductions entre problèmes NP-complets. Résultat du programme à inclure avec statut PROUVÉ : lemme L-02, le tableau d'une machine à espace s a une largeur de chemin au plus 4s+1, indépendante du nombre de pas t (vérifié expérimentalement pour 17, 25, 33, 41) ; signaler que les heuristiques de largeur peuvent surestimer fortement (255 au lieu de 41)." "Turing 1936 (On computable numbers, with an application to the Entscheidungsproblem) ; Tseitin 1968 (On the complexity of derivation in propositional calculus) ; Savitch 1970 (Relationships between nondeterministic and deterministic tape complexities) ; Cook 1971 (The complexity of theorem-proving procedures) ; Levin 1973 (Universal sequential search problems) ; Pippenger et Fischer 1979 (Relations among complexity measures) ; Papadimitriou 1994 (Computational Complexity) ; Arora et Barak 2009 (Computational Complexity: A Modern Approach) ; Biere, Heule, van Maaren et Walsh 2009 (Handbook of Satisfiability) ; Jukna 2012 (Boolean Function Complexity: Advances and Frontiers)" &
livre T7 "Des Circuits aux Réseaux de Neurones" "traductions circuits booléens et SAT vers réseaux de neurones et retour : compilation porte par porte en neurones à seuil, circuits à seuil de profondeur bornée, taille des poids, extraction d'un circuit à partir d'un réseau entraîné, largeur structurelle conservée ou perdue, réseaux comme solveurs approchés de contraintes (statut à préciser). Résultats du programme avec statut PROUVÉ : L-01 (Tseitin, largeur au plus (k+1)(w+1)-1) et L-03 (compilation, poids entiers au plus 2, facteur k+2) ; avec statut EXPÉRIMENTAL : réseaux 16-16 entraînés puis élagués, largeur 11 à 14 contre 1 à 3 pour les compilés (élagage grossier, limite à signaler)." "McCulloch et Pitts 1943 (A logical calculus of the ideas immanent in nervous activity) ; Tseitin 1968 (On the complexity of derivation in propositional calculus) ; Minsky et Papert 1969 (Perceptrons) ; Cook 1971 (The complexity of theorem-proving procedures) ; Hajnal, Maass, Pudlák, Szegedy et Turán 1993 (Threshold circuits of bounded depth) ; Håstad 1994 (On the size of weights for threshold gates) ; Biere, Heule, van Maaren et Walsh 2009 (Handbook of Satisfiability) ; Jukna 2012 (Boolean Function Complexity: Advances and Frontiers) ; Telgarsky 2016 (Benefits of depth in neural networks) ; Merrill et Sabharwal 2023 (The parallelism tradeoff: limitations of log-precision transformers)" &
livre T8 "Du Lambda-calcul aux Réseaux de Neurones" "traductions entre lambda-calcul et réseaux de neurones : représenter des termes et des fonctions d'ordre supérieur dans des réseaux, simuler la réduction par des réseaux récurrents via une machine intermédiaire, coût de la composition, absence de traduction directe connue efficace (statut OUVERT à affirmer clairement), ce que le partage et la liaison des variables deviennent dans un réseau, attention et substitution comme analogie seulement (à marquer CONJECTURE ou analogie, jamais comme résultat)." "Church 1936 (An unsolvable problem of elementary number theory) ; McCulloch et Pitts 1943 (A logical calculus of the ideas immanent in nervous activity) ; Howard 1980 (The formulae-as-types notion of construction) ; Barendregt 1984 (The Lambda Calculus: Its Syntax and Semantics) ; Siegelmann et Sontag 1995 (On the computational power of neural nets) ; Pierce 2002 (Types and Programming Languages) ; Goodfellow, Bengio et Courville 2016 (Deep Learning) ; Vaswani et al. 2017 (Attention is all you need) ; Pérez, Marinković et Barceló 2019 (On the Turing completeness of modern neural network architectures)" &
livre T9 "Des Machines de Turing aux Réseaux de Neurones" "traductions entre machines de Turing et réseaux de neurones : automates finis et réseaux de McCulloch-Pitts (Kleene), réseaux récurrents à poids rationnels et Turing-complétude (Siegelmann-Sontag), rôle crucial de la précision, transformers et Turing-complétude sous hypothèses (précision arbitraire), limites à précision logarithmique, coût en temps et en mémoire de chaque simulation, ce qui se perd quand la précision est bornée." "Turing 1936 (On computable numbers, with an application to the Entscheidungsproblem) ; McCulloch et Pitts 1943 (A logical calculus of the ideas immanent in nervous activity) ; Kleene 1956 (Representation of events in nerve nets and finite automata) ; Hopfield 1982 (Neural networks and physical systems with emergent collective computational abilities) ; Siegelmann et Sontag 1995 (On the computational power of neural nets) ; Arora et Barak 2009 (Computational Complexity: A Modern Approach) ; Vaswani et al. 2017 (Attention is all you need) ; Pérez, Marinković et Barceló 2019 (On the Turing completeness of modern neural network architectures) ; Merrill et Sabharwal 2023 (The parallelism tradeoff: limitations of log-precision transformers)" &
livre T9b "Du Lambda-calcul aux Preuves et à SAT" "traductions entre lambda-calcul typé, preuves et SAT : correspondance de Curry-Howard (propositions comme types, preuves comme programmes, normalisation comme élimination des coupures), logique propositionnelle et SAT, systèmes de preuve propositionnels et leur efficacité relative (Cook-Reckhow), résolution et ses bornes inférieures (Haken, principe des tiroirs), lien entre P différent de NP et coNP et taille des preuves, ce que la taille d'un terme de preuve mesure." "Tseitin 1968 (On the complexity of derivation in propositional calculus) ; Cook 1971 (The complexity of theorem-proving procedures) ; Cook et Reckhow 1979 (The relative efficiency of propositional proof systems) ; Howard 1980 (The formulae-as-types notion of construction) ; Barendregt 1984 (The Lambda Calculus: Its Syntax and Semantics) ; Haken 1985 (The intractability of resolution) ; Girard, Lafont et Taylor 1989 (Proofs and Types) ; Pierce 2002 (Types and Programming Languages) ; Biere, Heule, van Maaren et Walsh 2009 (Handbook of Satisfiability) ; Pipatsrisawat et Darwiche 2011 (On the power of clause-learning SAT solvers as resolution engines)" &
wait
